import http from 'node:http';
import https from 'node:https';
import { hostname } from 'node:os';
import { randomUUID } from 'node:crypto';
import { sign } from './signing.js';
import { urlProblem, guardedLookup } from './ssrf.js';

// The delivery queue lives in MongoDB (calm_webhook_deliveries). Workers claim one
// delivery at a time with findOneAndUpdate, so any number of instances can send without
// sending twice. A delivery is 'pending' (due now or waiting for a retry), 'sending',
// 'succeeded' or 'failed' (every retry used, 410 Gone, or endpoint disabled).

const RESPONSE_LOG_CHARS = 1024; // what the delivery log keeps of the receiver's answer
const RESPONSE_READ_LIMIT = 64 * 1024; // stop downloading huge answers nobody will read
const ATTEMPT_LOG_SIZE = 20;

/** Parse Retry-After (seconds or an HTTP date) into milliseconds. */
function retryAfterMs(value) {
  if (!value) return 0;
  if (/^\d+$/.test(value)) return Number(value) * 1000;
  const at = Date.parse(value);
  return Number.isNaN(at) ? 0 : Math.max(0, at - Date.now());
}

/** A short, user-facing reason for a network error. */
function describe(err, timeoutMs) {
  if (err?.name === 'AbortError' || err?.name === 'TimeoutError' || err?.code === 'ABORT_ERR') return `No answer within ${timeoutMs / 1000}s`;
  if (err?.code === 'ESSRF') return err.message;
  if (err?.code === 'ECONNREFUSED') return 'Connection refused';
  if (err?.code === 'ENOTFOUND' || err?.code === 'EAI_AGAIN') return 'Host not found';
  if (err?.code === 'ECONNRESET') return 'Connection reset by the receiver';
  return [err?.code, err?.message].filter(Boolean).join(': ') || 'Request failed';
}

/**
 * POST a body and resolve with { statusCode, response, retryAfter, durationMs } or
 * { error, durationMs }. Never rejects. Uses node:http(s) rather than fetch so that the
 * connection goes to the address guardedLookup checked; redirects are never followed.
 */
function post(url, { headers, body, timeoutMs, lookup, agents }) {
  const started = performance.now();
  return new Promise((resolve) => {
    let settled = false;
    let response = null;
    const chunks = [];
    let size = 0;
    const done = (result) => {
      if (settled) return;
      settled = true;
      resolve({ ...result, durationMs: Math.round(performance.now() - started) });
    };
    const answered = () =>
      done({ statusCode: response.statusCode, retryAfter: response.headers['retry-after'], response: Buffer.concat(chunks).toString('utf8').slice(0, RESPONSE_LOG_CHARS) });

    let req;
    try {
      const target = new URL(url);
      req = (target.protocol === 'https:' ? https : http).request(
        target,
        {
          method: 'POST',
          headers: { ...headers, 'content-length': Buffer.byteLength(body) },
          lookup,
          agent: agents[target.protocol],
          signal: AbortSignal.timeout(timeoutMs),
        },
        (res) => {
          response = res;
          res.on('data', (chunk) => {
            if (size < RESPONSE_LOG_CHARS) chunks.push(chunk);
            size += chunk.length;
            if (size > RESPONSE_READ_LIMIT) res.destroy();
          });
          res.on('end', answered);
          res.on('close', answered);
          res.on('error', () => {}); // 'close' follows and reports the status we already have
        },
      );
    } catch (err) {
      return done({ error: describe(err, timeoutMs) });
    }
    // An error after the status line arrived (timeout while reading the body) still has an answer.
    req.on('error', (err) => (response ? answered() : done({ error: describe(err, timeoutMs) })));
    req.end(body);
  });
}

export function createDeliveries({ app, Webhook, Delivery, settings, open, onDisable }) {
  const { schedule, timeoutMs, pollMs, concurrency } = settings;
  const workerId = `${hostname()}:${process.pid}:${randomUUID().slice(0, 8)}`;
  const lookup = guardedLookup({ allowPrivate: settings.url.allowPrivate });
  // Own agents: sockets are only ever opened through guardedLookup, and keep-alive
  // connections are reused between deliveries to the same receiver.
  const agents = { 'http:': new http.Agent({ keepAlive: true, maxSockets: 50 }), 'https:': new https.Agent({ keepAlive: true, maxSockets: 50 }) };

  let timer = null;
  let stopping = false;
  let ticking = false;
  let again = false;
  let running = 0;
  let ticks = 0;
  const inflight = new Set();

  const keepUntil = () => new Date(Date.now() + settings.keepMs);
  const unlock = { lockedAt: 1, lockedBy: 1 };

  /** How long to wait before the next attempt, or null when every retry is used. */
  function retryDelay(attempts, retryAfter) {
    if (attempts > schedule.length) return null;
    // Jitter (+-20%) so a receiver that was down is not hit by every retry at the same moment.
    const delay = Math.round(schedule[attempts - 1] * (0.8 + Math.random() * 0.4));
    const asked = retryAfterMs(retryAfter);
    return asked ? Math.max(delay, Math.min(asked, schedule.at(-1))) : delay;
  }

  async function send(endpoint, delivery) {
    // Checked again on every attempt: the URL may predate a stricter configuration.
    const problem = await urlProblem(endpoint.url, { ...settings.url, resolve: false });
    if (problem) return { error: `Refused: ${problem}`, durationMs: 0 };
    const body = open(delivery.body);
    const timestamp = Math.floor(Date.now() / 1000);
    // During a rotation the old secret signs too, so receivers can switch without downtime.
    const secrets = [open(endpoint.secret)];
    if (endpoint.previousSecret && endpoint.previousSecretExpiresAt > new Date()) secrets.push(open(endpoint.previousSecret));
    const headers = {
      'content-type': 'application/json',
      'user-agent': settings.userAgent,
      'webhook-id': delivery.messageId,
      'webhook-timestamp': String(timestamp),
      'webhook-signature': secrets.map((s) => sign(s, delivery.messageId, timestamp, body)).join(' '),
    };
    return post(endpoint.url, { headers, body, timeoutMs, lookup, agents });
  }

  async function record(delivery, endpoint, result) {
    const now = new Date();
    const ok = result.statusCode >= 200 && result.statusCode < 300;
    const error = ok ? null : (result.error ?? `HTTP ${result.statusCode}`);
    const statusCode = result.statusCode ?? null;
    const attempt = { at: now, statusCode, durationMs: result.durationMs, error };
    const last = { lastAttemptAt: now, lastStatusCode: statusCode, lastDurationMs: result.durationMs, lastError: error, lastResponse: result.response ?? null };
    const log = { log: { $each: [attempt], $slice: -ATTEMPT_LOG_SIZE } };

    if (ok) {
      await Delivery.updateOne({ _id: delivery._id }, { $set: { ...last, status: 'succeeded', deliveredAt: now, nextAttemptAt: null, expiresAt: keepUntil() }, $unset: unlock, $push: log });
      await Webhook.updateOne({ _id: endpoint._id }, { $set: { lastSuccessAt: now, lastStatusCode: statusCode, lastError: null, failedAttempts: 0, failedDeliveries: 0, failingSince: null } });
      return;
    }

    // 410 Gone: the receiver asks us to stop (Standard Webhooks). Anything else is retried.
    const gone = statusCode === 410;
    const wait = gone ? null : retryDelay(delivery.attempts, result.retryAfter);
    const next = wait === null ? { status: 'failed', nextAttemptAt: null, expiresAt: keepUntil() } : { status: 'pending', nextAttemptAt: new Date(now.getTime() + wait) };
    await Delivery.updateOne({ _id: delivery._id }, { $set: { ...last, ...next }, $unset: unlock, $push: log });
    await Webhook.updateOne({ _id: endpoint._id }, { $set: { lastFailureAt: now, lastStatusCode: statusCode, lastError: error }, $inc: { failedAttempts: 1 } });
    await Webhook.updateOne({ _id: endpoint._id, failingSince: null }, { $set: { failingSince: now } });

    if (gone) return onDisable(endpoint._id, 'gone');
    if (wait !== null) return;
    const updated = await Webhook.findOneAndUpdate({ _id: endpoint._id }, { $inc: { failedDeliveries: 1 } }, { returnDocument: 'after' }).lean();
    if (settings.disableAfterFailures > 0 && updated?.failedDeliveries >= settings.disableAfterFailures) await onDisable(endpoint._id, 'failing');
  }

  async function execute(delivery) {
    const endpoint = await Webhook.findById(delivery.webhook).select('+secret +previousSecret').lean();
    if (!endpoint) return Delivery.deleteOne({ _id: delivery._id });
    if (!endpoint.enabled) {
      return Delivery.updateOne(
        { _id: delivery._id },
        { $set: { status: 'failed', lastError: 'Endpoint is disabled', nextAttemptAt: null, expiresAt: keepUntil() }, $unset: unlock },
      );
    }
    await record(delivery, endpoint, await send(endpoint, delivery));
  }

  /** Execute one claimed delivery; a bug or a database error must not leave it stuck in 'sending'. */
  async function run(delivery) {
    try {
      await execute(delivery);
    } catch (err) {
      app.log.error('webhooks: delivery attempt crashed', { err, delivery: String(delivery._id) });
      const wait = retryDelay(delivery.attempts);
      await Delivery.updateOne(
        { _id: delivery._id },
        {
          $set: wait === null
            ? { status: 'failed', lastError: 'Internal error', nextAttemptAt: null, expiresAt: keepUntil() }
            : { status: 'pending', lastError: 'Internal error', nextAttemptAt: new Date(Date.now() + wait) },
          $unset: unlock,
        },
      ).catch(() => {});
    }
  }

  const claim = () =>
    Delivery.findOneAndUpdate(
      { status: 'pending', nextAttemptAt: { $lte: new Date() } },
      { $set: { status: 'sending', lockedAt: new Date(), lockedBy: workerId }, $inc: { attempts: 1 } },
      { sort: { nextAttemptAt: 1 }, returnDocument: 'after' },
    ).lean();

  async function fill() {
    if (++ticks % 60 === 0) {
      // Put back deliveries whose worker died mid-send (crash, kill -9, deploy).
      await Delivery.updateMany(
        { status: 'sending', lockedAt: { $lt: new Date(Date.now() - timeoutMs - 60_000) } },
        { $set: { status: 'pending', nextAttemptAt: new Date() }, $unset: unlock },
      );
    }
    while (!stopping && running < concurrency) {
      const delivery = await claim();
      if (!delivery) break;
      running++;
      const p = run(delivery).finally(() => {
        running--;
        inflight.delete(p);
        kick(); // a slot is free: take the next due delivery without waiting for the poll
      });
      inflight.add(p);
    }
  }

  async function tick() {
    if (ticking) {
      again = true;
      return;
    }
    ticking = true;
    try {
      do {
        again = false;
        await fill();
      } while (again && !stopping);
    } finally {
      ticking = false;
    }
  }

  const safeTick = () => tick().catch((err) => app.log.error('webhooks: worker tick failed', { err }));

  /** Look for due deliveries now instead of at the next poll. */
  function kick() {
    if (timer && !stopping) setImmediate(safeTick);
  }

  /** Mark a delivery as being sent by this process, send it now and return it updated. */
  async function sendNow(delivery) {
    await run(delivery);
    return Delivery.findById(delivery._id).lean();
  }

  return {
    workerId,
    get running() {
      return Boolean(timer);
    },

    /** Queue deliveries ({ webhook, type, messageId, body }) for the worker. */
    async enqueue(rows) {
      await Delivery.insertMany(rows.map((row) => ({ ...row, status: 'pending', nextAttemptAt: new Date(), expiresAt: keepUntil() })));
      kick();
    },

    /** Create a delivery and send it right away, in this request (test events). */
    async deliverNow(row) {
      const delivery = await Delivery.create({ ...row, status: 'sending', attempts: 1, lockedAt: new Date(), lockedBy: workerId, nextAttemptAt: null, expiresAt: keepUntil() });
      return sendNow(delivery.toObject());
    },

    /**
     * Send an existing delivery again now, with a fresh retry schedule. Same webhook-id, so
     * receivers that already processed it can skip it. Null when it is being sent right now.
     */
    async retryNow(webhookId, deliveryId) {
      const delivery = await Delivery.findOneAndUpdate(
        { _id: deliveryId, webhook: webhookId, status: { $ne: 'sending' } },
        { $set: { status: 'sending', attempts: 1, lockedAt: new Date(), lockedBy: workerId, nextAttemptAt: null, expiresAt: keepUntil() } },
        { returnDocument: 'after' },
      ).lean();
      return delivery ? sendNow(delivery) : null;
    },

    /** Deliver everything that is due now, one by one (tests and scripts). */
    async drain() {
      for (let i = 0; i < 1000; i++) {
        const delivery = await claim();
        if (!delivery) break;
        await run(delivery);
      }
      await Promise.all([...inflight]);
    },

    start() {
      stopping = false;
      timer = setInterval(safeTick, pollMs);
      timer.unref();
      app.log.info(`Webhooks worker started (every ${pollMs}ms, ${concurrency} at a time)`);
      kick();
    },

    async stop() {
      stopping = true;
      clearInterval(timer);
      timer = null;
      // In-flight requests end within timeoutMs; never hold shutdown longer than that.
      await Promise.race([Promise.all([...inflight]), new Promise((resolve) => setTimeout(resolve, timeoutMs + 1000).unref())]);
      agents['http:'].destroy();
      agents['https:'].destroy();
    },
  };
}

import { definePlugin, f, serialize, evaluatePolicy, parsePolicy, isEncrypted, CalmError, badRequest, unauthorized, forbidden, notFound, conflict, validationError } from '#calm';
import { newSecret, newMessageId, verifyWebhook } from './signing.js';
import { urlProblem } from './ssrf.js';
import { createDeliveries } from './delivery.js';

// Outgoing webhooks. Users subscribe a URL to resource events ('order.created', 'order.*')
// and receive every change they are allowed to read, serialized exactly like the API would
// return it to them. Admins can subscribe with scope 'global' to receive every record.
//
//  - Signed with Standard Webhooks headers; receivers check them with verifyWebhook().
//  - Queued in MongoDB, retried with backoff, logged per endpoint (calm_webhook_deliveries).
//  - SSRF protection: only public addresses, checked when saved and on every delivery.
//  - Signing secrets and queued payloads are encrypted at rest when CALM_ENCRYPTION_KEYS is set.

export { verifyWebhook, WebhookVerificationError } from './signing.js';

const ACTIONS = ['created', 'updated', 'deleted', 'restored'];
const RESOURCE_EVENT = /^([\w-]+)\.(created|updated|deleted|restored)$/;
const EVENT_PATTERN = /^([a-z][\w-]*)\.(\*|[a-z]+)$/;
const OBJECT_ID = /^[a-f\d]{24}$/i;
const DELIVERY_STATUSES = ['pending', 'sending', 'succeeded', 'failed'];
const PAYLOAD_PREVIEW_CHARS = 2048;
const UNITS = { ms: 1, s: 1000, m: 60_000, h: 3_600_000, d: 86_400_000 };

/** 5000, '5s', '2m', '6h' -> milliseconds. */
function toMs(value, name) {
  if (typeof value === 'number' && Number.isFinite(value) && value >= 0) return value;
  const m = /^(\d+(?:\.\d+)?)\s*(ms|s|m|h|d)$/.exec(String(value).trim());
  if (!m) throw new Error(`webhooks: ${name} must be milliseconds or a duration like '30s', '5m', '2h' (got ${JSON.stringify(value)})`);
  return Number(m[1]) * UNITS[m[2]];
}

const hostOf = (url) => {
  try {
    return new URL(url).host;
  } catch {
    return String(url);
  }
};

export default definePlugin({
  name: 'webhooks',
  env: {
    WEBHOOKS_WORKER: 'Set to "off" on instances that should not send webhooks (default on)',
  },
  // Override in calm.config.js: blocks: { webhooks: { maxEndpointsPerUser: 5 } }
  options: {
    policy: 'authenticated', // who may create and manage their own endpoints
    globalPolicy: 'admin', // who may create scope: 'global' endpoints (every record, admin view)
    allowPrivate: null, // call localhost and private networks? null: only in development and test
    requireHttps: null, // refuse http:// URLs? null: only in production
    maxEndpointsPerUser: 10,
    maxEventsPerEndpoint: 20,
    maxUrlLength: 2048,
    retrySchedule: ['5s', '30s', '2m', '10m', '30m', '2h', '6h'], // waits between attempts, then failed
    timeoutMs: 10_000,
    pollMs: 1000,
    concurrency: 10, // deliveries in flight per instance
    disableAfterFailures: 5, // deliveries in a row that failed every retry (0: never disable)
    keepDeliveriesDays: 14, // delivery log retention (TTL index)
    secretGraceHours: 24, // after a rotation the old secret also signs for this long
    notifyOwner: true, // email the owner when an endpoint is turned off automatically
  },
  setup(calm, options) {
    const { mode } = calm.config;
    if (!Array.isArray(options.retrySchedule)) throw new Error('webhooks: retrySchedule must be an array, e.g. [\'5s\', \'1m\']');
    const settings = {
      schedule: options.retrySchedule.map((v, i) => toMs(v, `retrySchedule[${i}]`)),
      timeoutMs: toMs(options.timeoutMs, 'timeoutMs'),
      pollMs: Math.max(10, toMs(options.pollMs, 'pollMs')), // 0 would be a busy loop
      concurrency: Math.max(1, Math.floor(Number(options.concurrency) || 1)),
      disableAfterFailures: Math.max(0, Number(options.disableAfterFailures) || 0),
      keepMs: Math.max(1, Number(options.keepDeliveriesDays) || 14) * UNITS.d,
      graceMs: Math.max(0, Number(options.secretGraceHours) || 0) * UNITS.h,
      url: {
        allowPrivate: options.allowPrivate ?? mode !== 'production',
        requireHttps: options.requireHttps ?? mode === 'production',
        maxLength: options.maxUrlLength,
      },
      userAgent: 'CalmAPI-Webhooks/1.0 (+https://www.standardwebhooks.com)',
    };
    const globalPolicy = parsePolicy(options.globalPolicy);
    const workerOn = calm.env('WEBHOOKS_WORKER', 'on') !== 'off';

    // Secrets must be readable again to sign, so they are encrypted (not hashed) at rest.
    // Payloads too: they can contain fields the resource stores .encrypted().
    const cipher = calm.app.cipher;
    const seal = (text) => (cipher ? cipher.encrypt(text) : text);
    const open = (stored) => {
      if (cipher) return cipher.decrypt(stored);
      if (isEncrypted(stored)) throw new Error('webhooks: data is encrypted but CALM_ENCRYPTION_KEYS is not set');
      return stored;
    };

    // ---- storage ---------------------------------------------------------------------
    const { Schema } = calm.mongoose;
    const webhookSchema = new Schema(
      {
        owner: { type: Schema.Types.ObjectId, ref: 'user', required: true },
        scope: { type: String, enum: ['own', 'global'], default: 'own' },
        url: { type: String, required: true },
        events: { type: [String], default: [] },
        description: String,
        secret: { type: String, select: false },
        previousSecret: { type: String, select: false },
        previousSecretExpiresAt: Date,
        enabled: { type: Boolean, default: true },
        disabledReason: { type: String, enum: ['gone', 'failing', 'manual'] },
        disabledAt: Date,
        failingSince: Date, // first failed attempt since the last success
        failedAttempts: { type: Number, default: 0 }, // attempts in a row
        failedDeliveries: { type: Number, default: 0 }, // deliveries in a row that used every retry
        lastSuccessAt: Date,
        lastFailureAt: Date,
        lastStatusCode: Number,
        lastError: String,
      },
      { collection: 'calm_webhooks', timestamps: true, versionKey: false },
    );
    webhookSchema.index({ owner: 1, _id: -1 });
    webhookSchema.index({ enabled: 1, events: 1 });
    const Webhook = calm.mongoose.model('calmWebhook', webhookSchema);

    const deliverySchema = new Schema(
      {
        webhook: { type: Schema.Types.ObjectId, required: true },
        type: { type: String, required: true },
        messageId: { type: String, required: true }, // webhook-id header, the same on every attempt
        body: { type: String, required: true }, // the exact JSON that is signed and sent
        status: { type: String, enum: DELIVERY_STATUSES, default: 'pending' },
        attempts: { type: Number, default: 0 },
        nextAttemptAt: Date,
        lockedAt: Date,
        lockedBy: String,
        lastAttemptAt: Date,
        lastStatusCode: Number,
        lastDurationMs: Number,
        lastError: String,
        lastResponse: String, // first 1 KB of the receiver's answer
        log: [{ _id: false, at: Date, statusCode: Number, durationMs: Number, error: String }],
        deliveredAt: Date,
        expiresAt: Date,
      },
      { collection: 'calm_webhook_deliveries', timestamps: true, versionKey: false },
    );
    deliverySchema.index({ status: 1, nextAttemptAt: 1 });
    deliverySchema.index({ webhook: 1, _id: -1 });
    // A date per document (not createdAt + N days) so changing keepDeliveriesDays never
    // conflicts with an existing index.
    deliverySchema.index({ expiresAt: 1 }, { expireAfterSeconds: 0 });
    const Delivery = calm.mongoose.model('calmWebhookDelivery', deliverySchema);

    const deliveries = createDeliveries({ app: calm.app, Webhook, Delivery, settings, open, onDisable: disable });

    // ---- views (never include secrets) ------------------------------------------------
    const view = (w) => ({
      id: String(w._id),
      url: w.url,
      events: w.events,
      description: w.description ?? null,
      scope: w.scope,
      enabled: w.enabled,
      status: !w.enabled ? 'disabled' : w.failingSince ? 'failing' : 'active',
      disabledReason: w.disabledReason ?? null,
      disabledAt: w.disabledAt ?? null,
      failingSince: w.failingSince ?? null,
      failedAttempts: w.failedAttempts ?? 0,
      lastSuccessAt: w.lastSuccessAt ?? null,
      lastFailureAt: w.lastFailureAt ?? null,
      lastStatusCode: w.lastStatusCode ?? null,
      lastError: w.lastError ?? null,
      createdAt: w.createdAt,
      updatedAt: w.updatedAt,
    });

    function preview(stored) {
      let text;
      try {
        text = open(stored);
      } catch {
        return { payload: null, payloadTruncated: false };
      }
      return text.length > PAYLOAD_PREVIEW_CHARS
        ? { payload: `${text.slice(0, PAYLOAD_PREVIEW_CHARS)}...`, payloadTruncated: true }
        : { payload: text, payloadTruncated: false };
    }

    const deliveryView = (d) => ({
      id: String(d._id),
      type: d.type,
      messageId: d.messageId,
      status: d.status,
      attempts: d.attempts,
      statusCode: d.lastStatusCode ?? null,
      durationMs: d.lastDurationMs ?? null,
      error: d.lastError ?? null,
      nextAttemptAt: d.status === 'pending' ? (d.nextAttemptAt ?? null) : null,
      lastAttemptAt: d.lastAttemptAt ?? null,
      deliveredAt: d.deliveredAt ?? null,
      response: d.lastResponse ?? null,
      ...preview(d.body),
      attemptLog: (d.log ?? []).map((a) => ({ at: a.at, statusCode: a.statusCode ?? null, durationMs: a.durationMs ?? null, error: a.error ?? null })),
      createdAt: d.createdAt,
    });

    // ---- rules --------------------------------------------------------------------------
    const mayGoGlobal = async (user) => {
      const decision = await evaluatePolicy(globalPolicy, { user, action: 'read' });
      return decision.allow && !decision.scope;
    };

    /** Why this list of event names cannot be used, or null. */
    async function eventsProblem(events, user, scope) {
      const followable = [...calm.app.registry.values()].filter((e) => e.def.options.webhooks !== false).map((e) => e.def.name);
      for (const event of events) {
        if (event === '*') continue;
        const m = EVENT_PATTERN.exec(event);
        if (!m) return `"${event}" is not an event name. Use "post.created", "post.*" or "*"`;
        const entry = calm.app.registry.get(m[1]);
        if (!entry || !followable.includes(m[1])) return `Unknown resource "${m[1]}". Webhooks can follow: ${followable.join(', ') || 'no resources'}`;
        if (m[2] !== '*' && !ACTIONS.includes(m[2])) return `Unknown event "${event}". Use ${ACTIONS.map((a) => `${m[1]}.${a}`).join(', ')} or ${m[1]}.*`;
        if (scope === 'own') {
          // Early feedback only: every delivery is checked again against the record itself.
          const read = await evaluatePolicy(entry.def.policy.read, { user, action: 'read' }).catch(() => ({ allow: true }));
          if (!read.allow) return `You cannot read ${m[1]} records, so "${event}" would never be delivered`;
        }
      }
      return null;
    }

    const me = (ctx) => {
      if (!ctx.user) throw unauthorized();
      return ctx.user;
    };

    async function findOwn(ctx, select) {
      const user = me(ctx);
      const id = String(ctx.params.id);
      if (!OBJECT_ID.test(id)) throw notFound('Webhook not found');
      const query = Webhook.findOne({ _id: id, owner: user.id });
      if (select) query.select(select);
      const w = await query.lean();
      if (!w) throw notFound('Webhook not found');
      return w;
    }

    const disabledError = () => badRequest('This endpoint is disabled. Turn it back on first: PATCH { "enabled": true }');

    // ---- turning endpoints off ----------------------------------------------------------
    const REASONS = {
      gone: 'it answered 410 Gone',
      failing: `${settings.disableAfterFailures} deliveries in a row failed after every retry`,
      manual: 'it was turned off',
    };

    async function disable(id, reason) {
      const endpoint = await Webhook.findOneAndUpdate(
        { _id: id, enabled: true },
        { $set: { enabled: false, disabledReason: reason, disabledAt: new Date() } },
        { returnDocument: 'after' },
      ).lean();
      if (!endpoint) return; // already off: report it once
      await Delivery.updateMany({ webhook: endpoint._id, status: 'pending' }, { $set: { status: 'failed', lastError: 'Endpoint was disabled', nextAttemptAt: null } });
      calm.events.emit('webhook.disabled', { webhook: view(endpoint), owner: String(endpoint.owner), reason });
      if (reason === 'manual') return;
      calm.log.warn(`webhooks: endpoint ${endpoint._id} turned off because ${REASONS[reason]}`, { host: hostOf(endpoint.url) });
      if (options.notifyOwner) await notifyOwner(endpoint, reason);
      refreshStats().catch(() => {});
    }

    // Standard Webhooks advises telling the owner through another channel.
    async function notifyOwner(endpoint, reason) {
      try {
        if (!calm.app.services.has('user')) return;
        const owner = await calm.app.model('user').findById(endpoint.owner).lean();
        if (!owner?.email) return;
        const api = `${calm.config.app.url.replace(/\/$/, '')}${calm.config.apiPrefix}/webhooks/${endpoint._id}`;
        await calm.mailer.send({
          to: owner.email,
          subject: `Webhook turned off: ${hostOf(endpoint.url)}`,
          text: [
            `Hello${owner.name ? ` ${owner.name}` : ''},`,
            '',
            `We stopped sending webhooks to ${endpoint.url} because ${REASONS[reason]}.`,
            '',
            `See what went wrong: GET ${api}/deliveries`,
            `When the receiver works again, turn it back on: PATCH ${api} with { "enabled": true }`,
          ].join('\n'),
          meta: { block: 'webhooks', webhook: String(endpoint._id), reason },
        });
      } catch (err) {
        calm.log.warn('webhooks: could not email the endpoint owner', { err: err.message });
      }
    }

    // ---- events -> deliveries -------------------------------------------------------------
    /** Endpoint owners as req.user would look; disabled and deleted users are left out. */
    async function loadOwners(ids) {
      if (!calm.app.services.has('user')) return new Map();
      const users = await calm.app.model('user').find({ _id: { $in: ids } }).lean();
      return new Map(users.filter((u) => u.status !== 'disabled').map((u) => [String(u._id), { ...u, id: String(u._id) }]));
    }

    /** The JSON body for one subscriber, or null when they may not see this record. */
    async function bodyFor(entry, doc, user, scope, event) {
      if (!user) return null;
      try {
        // Global: every record, whatever its read policy, but still inside the owner's scope().
        const allowed = scope === 'global'
          ? (await mayGoGlobal(user)) && (await calm.app.inScope(entry, doc, user, { deleted: event.deleted }))
          : await calm.app.canRead(entry, doc, user, { deleted: event.deleted });
        if (!allowed) return null;
        // Serialized for this user: hidden fields never, visibleTo() fields only if they may.
        const data = await serialize(entry.def, doc, { user, registry: calm.app.registry });
        return JSON.stringify({ type: event.type, timestamp: event.timestamp, data });
      } catch (err) {
        calm.log.warn(`webhooks: ${event.type} not sent to one subscriber, the visibility check failed`, { err: err.message });
        return null;
      }
    }

    async function dispatch(entry, type, doc) {
      const endpoints = await Webhook.find({ enabled: true, events: { $in: ['*', `${entry.def.name}.*`, type] } }).lean();
      if (!endpoints.length) return;
      const owners = await loadOwners(endpoints.map((w) => w.owner));
      // One message id per event: receivers subscribed twice can still recognise it.
      const event = { type, timestamp: new Date().toISOString(), messageId: newMessageId(), deleted: type.endsWith('.deleted') };
      const bodies = new Map();
      const rows = [];
      for (const w of endpoints) {
        const key = `${w.owner}:${w.scope}`;
        if (!bodies.has(key)) bodies.set(key, await bodyFor(entry, doc, owners.get(String(w.owner)), w.scope, event));
        const body = bodies.get(key);
        if (body) rows.push({ webhook: w._id, type, messageId: event.messageId, body: seal(body) });
      }
      if (rows.length) await deliveries.enqueue(rows);
    }

    calm.on('*', async (payload, name) => {
      const m = RESOURCE_EVENT.exec(name);
      if (!m || !payload?.doc) return;
      const entry = calm.app.registry.get(m[1]);
      if (!entry || entry.def.options.webhooks === false) return;
      await dispatch(entry, name, payload.doc);
    });

    // A deleted user's endpoints and logs go with them.
    calm.on('user.deleted', async ({ doc }) => {
      const ids = (await Webhook.find({ owner: doc._id }).select('_id').lean()).map((w) => w._id);
      if (!ids.length) return;
      await Delivery.deleteMany({ webhook: { $in: ids } });
      await Webhook.deleteMany({ _id: { $in: ids } });
    });

    // ---- API --------------------------------------------------------------------------------
    const tags = ['webhooks'];
    const policy = options.policy;
    const urlField = f.url().max(settings.url.maxLength);
    const eventsField = f
      .array(f.string().max(100))
      .min(1, 'Pick at least one event')
      .max(options.maxEventsPerEndpoint, `At most ${options.maxEventsPerEndpoint} events per endpoint`);
    const descriptionField = f.string().max(200);
    const manualRateLimit = { windowMs: 60_000, max: 10 }; // these routes make the server send requests

    calm.routes(
      (r) => {
        r.post(
          '/',
          {
            policy,
            status: 201,
            summary: 'Create a webhook endpoint (the response shows its signing secret, once)',
            input: { url: urlField.required(), events: eventsField.required(), description: descriptionField, scope: f.enum(['own', 'global']) },
            tags,
          },
          async (ctx) => {
            const user = me(ctx);
            const { url, description, scope = 'own' } = ctx.body;
            const events = [...new Set(ctx.body.events)];
            if (scope === 'global' && !(await mayGoGlobal(user))) throw forbidden('Only admins can create global webhooks');
            const count = await Webhook.countDocuments({ owner: user.id });
            if (count >= options.maxEndpointsPerUser) {
              throw new CalmError(409, 'LIMIT_REACHED', `You already have ${count} webhook endpoints, the most allowed. Delete one first.`);
            }
            const problems = {};
            const urlIssue = await urlProblem(url, settings.url);
            if (urlIssue) problems.url = urlIssue;
            const eventIssue = await eventsProblem(events, user, scope);
            if (eventIssue) problems.events = eventIssue;
            if (Object.keys(problems).length) throw validationError(problems);

            const secret = newSecret();
            const w = await Webhook.create({ owner: user.id, scope, url, events, description: description ?? undefined, secret: seal(secret) });
            return { ...view(w.toObject()), secret };
          },
        );

        r.get('/', { policy, summary: 'Your webhook endpoints', tags }, async (ctx) =>
          (await Webhook.find({ owner: me(ctx).id }).sort({ _id: -1 }).lean()).map(view),
        );

        r.get('/:id', { policy, summary: 'One of your webhook endpoints', tags }, async (ctx) => view(await findOwn(ctx)));

        r.patch(
          '/:id',
          {
            policy,
            summary: 'Change the URL, events or description, or turn an endpoint on or off',
            input: { url: urlField, events: eventsField, description: descriptionField, enabled: f.boolean() },
            tags,
          },
          async (ctx) => {
            const w = await findOwn(ctx);
            const body = ctx.body;
            const problems = {};
            if (body.url === null) problems.url = 'Is required';
            else if (body.url !== undefined) problems.url = await urlProblem(body.url, settings.url);
            if (body.events === null) problems.events = 'Is required';
            else if (body.events !== undefined) problems.events = await eventsProblem(body.events, ctx.user, w.scope);
            for (const key of Object.keys(problems)) if (!problems[key]) delete problems[key];
            if (Object.keys(problems).length) throw validationError(problems);

            const $set = {};
            const $unset = {};
            if (body.url !== undefined) $set.url = body.url;
            if (body.events !== undefined) $set.events = [...new Set(body.events)];
            if (body.description === null) $unset.description = 1;
            else if (body.description !== undefined) $set.description = body.description;
            if (body.enabled === true && !w.enabled) {
              Object.assign($set, { enabled: true, failedAttempts: 0, failedDeliveries: 0, failingSince: null });
              Object.assign($unset, { disabledReason: 1, disabledAt: 1 });
            }
            const update = {};
            if (Object.keys($set).length) update.$set = $set;
            if (Object.keys($unset).length) update.$unset = $unset;
            if (Object.keys(update).length) await Webhook.updateOne({ _id: w._id }, update);
            if (body.enabled === false && w.enabled) await disable(w._id, 'manual');
            return view(await Webhook.findById(w._id).lean());
          },
        );

        r.delete('/:id', { policy, summary: 'Delete a webhook endpoint and its delivery log', tags }, async (ctx) => {
          const w = await findOwn(ctx);
          await Webhook.deleteOne({ _id: w._id });
          await Delivery.deleteMany({ webhook: w._id });
        });

        r.post(
          '/:id/rotate-secret',
          { policy, summary: 'New signing secret (shown once); the old one keeps signing during the grace period', tags },
          async (ctx) => {
            const w = await findOwn(ctx, '+secret');
            const secret = newSecret();
            const update = { $set: { secret: seal(secret) } };
            if (settings.graceMs > 0) Object.assign(update.$set, { previousSecret: w.secret, previousSecretExpiresAt: new Date(Date.now() + settings.graceMs) });
            else update.$unset = { previousSecret: 1, previousSecretExpiresAt: 1 };
            const updated = await Webhook.findOneAndUpdate({ _id: w._id }, update, { returnDocument: 'after' }).lean();
            return { ...view(updated), secret, previousSecretExpiresAt: updated.previousSecretExpiresAt ?? null };
          },
        );

        r.post(
          '/:id/test',
          { policy, summary: 'Send a webhook.test event now and return the delivery', rateLimit: manualRateLimit, tags },
          async (ctx) => {
            const w = await findOwn(ctx);
            if (!w.enabled) throw disabledError();
            const body = JSON.stringify({
              type: 'webhook.test',
              timestamp: new Date().toISOString(),
              data: { webhook: String(w._id), message: `Test event from ${calm.config.app.name}` },
            });
            return deliveryView(await deliveries.deliverNow({ webhook: w._id, type: 'webhook.test', messageId: newMessageId(), body: seal(body) }));
          },
        );

        r.get('/:id/deliveries', { policy, summary: 'Recent deliveries: status code, duration, attempts, error, next retry', tags }, async (ctx) => {
          const w = await findOwn(ctx);
          const filter = { webhook: w._id };
          if (DELIVERY_STATUSES.includes(ctx.query.status)) filter.status = ctx.query.status;
          const limit = Math.min(Math.max(Math.floor(Number(ctx.query.limit)) || 50, 1), 100);
          return (await Delivery.find(filter).sort({ _id: -1 }).limit(limit).lean()).map(deliveryView);
        });

        r.post(
          '/:id/deliveries/:deliveryId/retry',
          { policy, summary: 'Send a delivery again now (same webhook-id, fresh retry schedule)', rateLimit: manualRateLimit, tags },
          async (ctx) => {
            const w = await findOwn(ctx);
            if (!w.enabled) throw disabledError();
            const deliveryId = String(ctx.params.deliveryId);
            if (!OBJECT_ID.test(deliveryId)) throw notFound('Delivery not found');
            const delivery = await deliveries.retryNow(w._id, deliveryId);
            if (delivery) return deliveryView(delivery);
            throw (await Delivery.exists({ _id: deliveryId, webhook: w._id })) ? conflict('This delivery is being sent right now') : notFound('Delivery not found');
          },
        );
      },
      { prefix: '/webhooks' },
    );

    // ---- health: doctor, devtools ---------------------------------------------------------------
    // Doctor checks are synchronous, so they read numbers refreshed in the background.
    let stats = null;
    async function refreshStats() {
      const failingFilter = { enabled: true, failingSince: { $ne: null } };
      const [total, enabled, failingCount, failing, autoDisabled] = await Promise.all([
        Webhook.countDocuments(),
        Webhook.countDocuments({ enabled: true }),
        Webhook.countDocuments(failingFilter),
        Webhook.find(failingFilter).sort({ failingSince: 1 }).limit(3).lean(),
        Webhook.countDocuments({ enabled: false, disabledReason: { $in: ['gone', 'failing'] } }),
      ]);
      stats = { total, enabled, failingCount, failing, autoDisabled };
      return stats;
    }

    calm.doctor(() => {
      const findings = [];
      const production = mode === 'production';
      if (!calm.app.auth) {
        findings.push({ level: 'error', id: 'webhooks-auth', title: 'The webhooks block needs auth', detail: 'Endpoints belong to users: keep config.auth enabled and the user resource in place.' });
      }
      if (production && settings.url.allowPrivate) {
        findings.push({ level: 'warn', id: 'webhooks-allow-private', title: 'Webhooks may call private addresses', detail: 'blocks.webhooks.allowPrivate is on in production: users can make this server call localhost, internal services and cloud metadata (SSRF). Remove it.' });
      }
      if (production && !cipher) {
        findings.push({ level: 'warn', id: 'webhooks-plaintext', title: 'Webhook secrets are stored unencrypted', detail: 'Set CALM_ENCRYPTION_KEYS (npx calm keygen --write) so signing secrets and queued payloads are encrypted at rest.' });
      }
      if (!workerOn) {
        findings.push({ level: 'info', id: 'webhooks-worker-off', title: 'Webhooks worker is off on this instance', detail: 'WEBHOOKS_WORKER=off: make sure another instance runs with it on, or nothing is delivered.' });
      }
      if (stats) {
        findings.push({
          level: 'info',
          id: 'webhooks-endpoints',
          title: `${stats.total} webhook endpoint${stats.total === 1 ? '' : 's'}, ${stats.enabled} enabled`,
          detail: stats.autoDisabled ? `${stats.autoDisabled} turned off automatically (410 Gone or failing). Owners turn them back on with PATCH /api/webhooks/:id.` : 'Users manage them at /api/webhooks.',
        });
        if (stats.failingCount) {
          const list = stats.failing.map((w) => `${hostOf(w.url)} since ${new Date(w.failingSince).toISOString()} (${w.lastError ?? 'error'})`).join('; ');
          findings.push({
            level: 'warn',
            id: 'webhooks-failing',
            title: `${stats.failingCount} webhook endpoint${stats.failingCount === 1 ? ' is' : 's are'} failing`,
            detail: `${list}. Deliveries are retried; see GET /api/webhooks/:id/deliveries.`,
          });
        }
      }
      return findings;
    });

    calm.devtools.panel('webhooks', async () => {
      const [endpoints, recent, pending] = await Promise.all([
        Webhook.find().sort({ _id: -1 }).limit(50).lean(),
        Delivery.find().sort({ _id: -1 }).limit(25).lean(),
        Delivery.countDocuments({ status: 'pending' }),
      ]);
      return {
        worker: deliveries.running ? deliveries.workerId : 'off',
        pending,
        endpoints: endpoints.map((w) => ({
          id: String(w._id),
          owner: String(w.owner),
          scope: w.scope,
          url: w.url,
          events: w.events.join(', '),
          status: view(w).status,
          failedAttempts: w.failedAttempts ?? 0,
          lastSuccessAt: w.lastSuccessAt ?? null,
          lastError: w.lastError ?? null,
        })),
        deliveries: recent.map((d) => ({
          id: String(d._id),
          webhook: String(d.webhook),
          type: d.type,
          status: d.status,
          attempts: d.attempts,
          statusCode: d.lastStatusCode ?? null,
          durationMs: d.lastDurationMs ?? null,
          error: d.lastError ?? null,
          nextAttemptAt: d.status === 'pending' ? d.nextAttemptAt : null,
          createdAt: d.createdAt,
        })),
      };
    });

    calm.provide('webhooks', { Webhook, Delivery, drain: deliveries.drain, refreshStats, verifyWebhook });

    // ---- lifecycle ------------------------------------------------------------------------------
    let statsTimer = null;
    calm.onStart(async () => {
      await Promise.all([Webhook.init(), Delivery.init()]);
      if (workerOn) deliveries.start();
      await refreshStats().catch((err) => calm.log.warn('webhooks: could not read endpoint stats', { err: err.message }));
      statsTimer = setInterval(() => refreshStats().catch(() => {}), 60_000);
      statsTimer.unref();
    });
    calm.onShutdown(async () => {
      clearInterval(statsTimer);
      await deliveries.stop();
    });
  },
});

import { createHmac, randomBytes, timingSafeEqual } from 'node:crypto';

// Signatures as the Standard Webhooks spec defines them (https://www.standardwebhooks.com):
//
//   webhook-id:        msg_...   same value on every retry, receivers use it to skip duplicates
//   webhook-timestamp: 1674087231   unix seconds of this attempt (replay protection)
//   webhook-signature: v1,<base64 HMAC-SHA256 of "id.timestamp.body">   space separated list
//
// Secrets look like whsec_<base64>; the HMAC key is the decoded bytes. Any Standard Webhooks
// library (npm: standardwebhooks, Svix, ...) can verify what this block sends.
//
// This file has no imports besides node:crypto: copy it into the app that receives the
// webhooks and call verifyWebhook() there.

const PREFIX = 'whsec_';
const DEFAULT_TOLERANCE_SECONDS = 5 * 60; // what the reference libraries accept

/** A new signing secret: 32 random bytes (the spec asks for 24 to 64). */
export const newSecret = () => `${PREFIX}${randomBytes(32).toString('base64')}`;

/** A message id. It goes into the signed content, so it must never contain a '.'. */
export const newMessageId = () => `msg_${randomBytes(16).toString('base64url')}`;

function keyOf(secret) {
  if (typeof secret !== 'string' || !secret) throw new WebhookVerificationError('The webhook secret is missing');
  const key = Buffer.from(secret.startsWith(PREFIX) ? secret.slice(PREFIX.length) : secret, 'base64');
  if (!key.length) throw new WebhookVerificationError('The webhook secret is not valid base64');
  return key;
}

/** The value of one signature: "v1,<base64>". body is the exact string (or Buffer) that is sent. */
export function sign(secret, id, timestamp, body) {
  const hmac = createHmac('sha256', keyOf(secret)).update(`${id}.${timestamp}.`).update(body);
  return `v1,${hmac.digest('base64')}`;
}

export class WebhookVerificationError extends Error {
  constructor(message) {
    super(message);
    this.name = 'WebhookVerificationError';
  }
}

/** Read a header from a plain object (any case), Node's req.headers or a fetch Headers. */
function header(headers, name) {
  if (!headers) return undefined;
  if (typeof headers.get === 'function') return headers.get(name) ?? undefined;
  const key = Object.keys(headers).find((k) => k.toLowerCase() === name);
  const value = key === undefined ? undefined : headers[key];
  return Array.isArray(value) ? value[0] : value;
}

/**
 * Check that a webhook really comes from the sender and is recent. Returns the parsed
 * payload ({ type, timestamp, data }) or throws WebhookVerificationError.
 *
 *   app.post('/hooks', express.raw({ type: 'application/json' }), (req, res) => {
 *     const event = verifyWebhook(process.env.WEBHOOK_SECRET, req.headers, req.body);
 *     res.sendStatus(204);
 *   });
 *
 * `body` must be the raw request body (string or Buffer): parsing the JSON and
 * serializing it again changes the bytes, and the signature no longer matches.
 */
export function verifyWebhook(secret, headers, body, { toleranceSeconds = DEFAULT_TOLERANCE_SECONDS, now = Date.now() } = {}) {
  const id = header(headers, 'webhook-id');
  const timestamp = header(headers, 'webhook-timestamp');
  const signatures = header(headers, 'webhook-signature');
  if (!id || !timestamp || !signatures) throw new WebhookVerificationError('Missing webhook-id, webhook-timestamp or webhook-signature header');
  if (typeof body !== 'string' && !(body instanceof Uint8Array)) {
    throw new WebhookVerificationError('Pass the raw request body (string or Buffer), not parsed JSON');
  }
  if (!/^\d{1,12}$/.test(String(timestamp))) throw new WebhookVerificationError('Invalid webhook-timestamp header');
  if (Math.abs(now / 1000 - Number(timestamp)) > toleranceSeconds) {
    throw new WebhookVerificationError('Timestamp is outside the allowed window (a replayed message, or a clock that is off)');
  }

  const raw = typeof body === 'string' ? Buffer.from(body, 'utf8') : Buffer.from(body);
  const expected = Buffer.from(sign(secret, id, timestamp, raw).slice(3), 'base64');
  // Several signatures are sent while a rotated secret is still valid: any one may match.
  const valid = String(signatures)
    .split(' ')
    .some((part) => {
      const [version, value] = part.split(',');
      if (version !== 'v1' || !value) return false;
      const given = Buffer.from(value, 'base64');
      return given.length === expected.length && timingSafeEqual(given, expected);
    });
  if (!valid) throw new WebhookVerificationError('No matching signature');

  try {
    return JSON.parse(raw.toString('utf8'));
  } catch {
    throw new WebhookVerificationError('Body is not valid JSON');
  }
}

import { lookup as dnsLookup } from 'node:dns';
import { BlockList, isIP } from 'node:net';

// Server-side request forgery protection. Webhook URLs come from users, and the server
// calls them: without these checks anyone could make it POST to localhost, the private
// network or the cloud metadata service (169.254.169.254) and read the answers in the
// delivery log.
//
// Only public unicast addresses are allowed. Host names are resolved and every address
// must be public, once when the URL is saved and again on every delivery: the request
// connects to the exact address that was checked (guardedLookup), so a DNS answer that
// changes between the check and the connection (DNS rebinding) cannot sneak through.

const PRIVATE_V4 = [
  ['0.0.0.0', 8], // "this network": 0.0.0.0 reaches localhost on Linux
  ['10.0.0.0', 8], // private
  ['100.64.0.0', 10], // carrier-grade NAT (Alibaba Cloud metadata is 100.100.100.200)
  ['127.0.0.0', 8], // loopback
  ['169.254.0.0', 16], // link-local, cloud metadata (AWS, GCP, Azure: 169.254.169.254)
  ['172.16.0.0', 12], // private
  ['192.0.0.0', 24], // IETF protocol assignments (Oracle Cloud metadata is 192.0.0.192)
  ['192.0.2.0', 24], // documentation
  ['192.88.99.0', 24], // 6to4 relay anycast
  ['192.168.0.0', 16], // private
  ['198.18.0.0', 15], // benchmarking
  ['198.51.100.0', 24], // documentation
  ['203.0.113.0', 24], // documentation
  ['224.0.0.0', 4], // multicast
  ['240.0.0.0', 4], // reserved and broadcast
];

const blocked4 = new BlockList();
for (const [net, prefix] of PRIVATE_V4) blocked4.addSubnet(net, prefix, 'ipv4');

// IPv6 is an allow list: global unicast (2000::/3) minus the reserved parts inside it.
// Everything else (::1, ::, fc00::/7 unique local incl. AWS fd00:ec2::254, fe80::/10,
// multicast, discard...) is refused.
const global6 = new BlockList();
global6.addSubnet('2000::', 3, 'ipv6');
const blocked6 = new BlockList();
blocked6.addSubnet('2001::', 23, 'ipv6'); // IETF protocol assignments, Teredo tunnels
blocked6.addSubnet('2001:db8::', 32, 'ipv6'); // documentation
blocked6.addSubnet('3fff::', 20, 'ipv6'); // documentation

/** The eight 16-bit groups of a valid IPv6 address. */
function groups(ip) {
  let s = ip.toLowerCase();
  if (s.includes('.')) {
    // Trailing dotted IPv4 (::ffff:127.0.0.1): rewrite it as two hex groups.
    const at = s.lastIndexOf(':');
    const [a, b, c, d] = s.slice(at + 1).split('.').map(Number);
    s = `${s.slice(0, at + 1)}${((a << 8) | b).toString(16)}:${((c << 8) | d).toString(16)}`;
  }
  const [head, tail] = s.split('::');
  const left = head ? head.split(':') : [];
  const right = tail ? tail.split(':') : [];
  const middle = s.includes('::') ? Array(8 - left.length - right.length).fill('0') : [];
  return [...left, ...middle, ...right].map((g) => parseInt(g, 16));
}

const v4 = (hi, lo) => `${hi >> 8}.${hi & 255}.${lo >> 8}.${lo & 255}`;

/** True only for public unicast IPv4/IPv6 addresses. Anything unparsable is not public. */
export function isPublicAddress(address) {
  const ip = String(address).replace(/^\[|\]$/g, '').replace(/%.*$/, '');
  const family = isIP(ip);
  if (family === 4) return !blocked4.check(ip, 'ipv4');
  if (family !== 6) return false;
  const g = groups(ip);
  // IPv6 forms that carry an IPv4 address are judged by the IPv4 address they reach.
  if (g.slice(0, 5).every((x) => x === 0) && g[5] === 0xffff) return isPublicAddress(v4(g[6], g[7])); // ::ffff:a.b.c.d
  if (g[0] === 0x64 && g[1] === 0xff9b && g.slice(2, 6).every((x) => x === 0)) return isPublicAddress(v4(g[6], g[7])); // NAT64
  if (g[0] === 0x2002) return isPublicAddress(v4(g[1], g[2])); // 6to4
  return global6.check(ip, 'ipv6') && !blocked6.check(ip, 'ipv6');
}

/** Every address a host name resolves to (the same resolver http.request uses). */
export const resolveAll = (host) =>
  new Promise((resolve, reject) => {
    dnsLookup(host, { all: true, verbatim: true }, (err, list) => (err ? reject(err) : resolve(list.map((a) => a.address))));
  });

const PRIVATE_MESSAGE = 'Must be a public address: localhost, private networks and cloud metadata addresses are refused';

/**
 * Why a webhook URL cannot be used, or null when it can. Messages are safe to show to the
 * user who typed the URL: they never include what a host name resolved to.
 *
 * @param {string} raw
 * @param {{ allowPrivate?: boolean, requireHttps?: boolean, maxLength?: number,
 *   resolve?: boolean, lookup?: (host: string) => Promise<string[]> }} [rules]
 *   resolve: false skips DNS (at send time guardedLookup checks the addresses instead).
 */
export async function urlProblem(raw, { allowPrivate = false, requireHttps = false, maxLength = 2048, resolve = true, lookup = resolveAll } = {}) {
  if (typeof raw !== 'string' || !raw) return 'Is required';
  if (raw.length > maxLength) return `Must be at most ${maxLength} characters`;
  let url;
  try {
    url = new URL(raw);
  } catch {
    return 'Must be a valid URL';
  }
  if (url.protocol !== 'https:' && url.protocol !== 'http:') return 'Must start with https:// or http://';
  if (requireHttps && url.protocol !== 'https:') return 'Must use https:// (payloads contain your data)';
  if (url.username || url.password) return 'Must not contain a user name or password (put a token in the path or query instead)';
  if (allowPrivate) return null;

  // The URL parser already turned tricks like http://2130706433/ or http://0x7f.1/ into 127.0.0.1.
  const host = url.hostname.replace(/^\[|\]$/g, '').replace(/\.$/, '').toLowerCase();
  if (!host) return 'Must have a host name';
  if (host === 'localhost' || host.endsWith('.localhost')) return PRIVATE_MESSAGE;
  if (isIP(host)) return isPublicAddress(host) ? null : PRIVATE_MESSAGE;
  if (!resolve) return null;

  let addresses;
  try {
    addresses = await lookup(host);
  } catch {
    return `Host ${host} could not be found`;
  }
  if (!addresses.length) return `Host ${host} could not be found`;
  return addresses.every(isPublicAddress) ? null : PRIVATE_MESSAGE;
}

/**
 * A `lookup` for http.request / net.connect that refuses host names resolving to any
 * non-public address. The connection then uses the addresses checked here, never a
 * second DNS answer.
 */
export function guardedLookup({ allowPrivate = false } = {}) {
  return (hostname, options, callback) => {
    if (typeof options === 'function') [callback, options] = [options, {}];
    dnsLookup(hostname, { ...options, all: true }, (err, addresses) => {
      if (err) return callback(err);
      if (!allowPrivate && (!addresses.length || !addresses.every((a) => isPublicAddress(a.address)))) {
        const refused = new Error(`Refused: ${hostname} resolves to a private or reserved address`);
        refused.code = 'ESSRF';
        return callback(refused);
      }
      if (options.all) return callback(null, addresses);
      callback(null, addresses[0].address, addresses[0].family);
    });
  };
}
